const fs = require('fs');
const { Document, Packer, Paragraph, TextRun, AlignmentType, HeadingLevel, PageBreak } = require('docx');

const doc = new Document({
  styles: {
    default: {
      document: {
        run: {
          font: "Times New Roman",
          size: 24 // 12pt
        }
      }
    },
    paragraphStyles: [
      {
        id: "Heading1",
        name: "Heading 1",
        basedOn: "Normal",
        next: "Normal",
        quickFormat: true,
        run: {
          size: 24,
          bold: true,
          font: "Times New Roman"
        },
        paragraph: {
          spacing: { before: 240, after: 120 },
          alignment: AlignmentType.CENTER
        }
      }
    ]
  },
  sections: [{
    properties: {
      page: {
        size: {
          width: 12240,   // 8.5 inches
          height: 15840   // 11 inches
        },
        margin: {
          top: 1440,    // 1 inch
          right: 1440,
          bottom: 1440,
          left: 1440
        }
      }
    },
    children: [
      // Header section
      new Paragraph({
        alignment: AlignmentType.CENTER,
        children: [
          new TextRun({
            text: "IN THE CIRCUIT COURT FOR WILLIAMSON COUNTY, TENNESSEE",
            size: 24
          })
        ]
      }),
      new Paragraph({
        alignment: AlignmentType.CENTER,
        children: [
          new TextRun({
            text: "AT FRANKLIN",
            size: 24
          })
        ],
        spacing: { after: 240 }
      }),

      // Case caption
      new Paragraph({
        children: [
          new TextRun({
            text: "ELIZABETH ANNE GIFFORD",
            size: 24
          })
        ]
      }),
      new Paragraph({
        children: [
          new TextRun({
            text: "Plaintiff/Wife,",
            size: 24
          })
        ],
        indent: { left: 720 }
      }),
      new Paragraph({
        children: [
          new TextRun({
            text: "v.",
            size: 24
          })
        ],
        spacing: { before: 120, after: 120 }
      }),
      new Paragraph({
        children: [
          new TextRun({
            text: "GRANT TAYLOR GIFFORD,",
            size: 24
          })
        ]
      }),
      new Paragraph({
        children: [
          new TextRun({
            text: " Defendant/Husband.",
            size: 24
          })
        ],
        indent: { left: 720 },
        spacing: { after: 120 }
      }),

      // Right-aligned docket info
      new Paragraph({
        alignment: AlignmentType.RIGHT,
        children: [
          new TextRun({
            text: ")",
            size: 24
          })
        ]
      }),
      new Paragraph({
        alignment: AlignmentType.RIGHT,
        children: [
          new TextRun({
            text: ")",
            size: 24
          })
        ]
      }),
      new Paragraph({
        alignment: AlignmentType.RIGHT,
        children: [
          new TextRun({
            text: ")",
            size: 24
          })
        ]
      }),
      new Paragraph({
        alignment: AlignmentType.RIGHT,
        children: [
          new TextRun({
            text: ")",
            size: 24
          })
        ]
      }),
      new Paragraph({
        alignment: AlignmentType.RIGHT,
        children: [
          new TextRun({
            text: ")",
            size: 24
          })
        ]
      }),
      new Paragraph({
        alignment: AlignmentType.RIGHT,
        children: [
          new TextRun({
            text: ")",
            size: 24
          })
        ]
      }),
      new Paragraph({
        alignment: AlignmentType.RIGHT,
        children: [
          new TextRun({
            text: ")",
            size: 24
          })
        ]
      }),
      new Paragraph({
        alignment: AlignmentType.RIGHT,
        children: [
          new TextRun({
            text: "Docket No. 25-CV-543",
            size: 24
          })
        ],
        spacing: { after: 240 }
      }),

      // Title
      new Paragraph({
        alignment: AlignmentType.CENTER,
        children: [
          new TextRun({
            text: "MARITAL DISSOLUTION AGREEMENT",
            bold: true,
            size: 24
          })
        ],
        spacing: { before: 240, after: 240 }
      }),

      // Opening paragraph
      new Paragraph({
        alignment: AlignmentType.JUSTIFIED,
        children: [
          new TextRun({
            text: "THIS MARITAL DISSOLUTION AGREEMENT made and entered into by and between Elizabeth Anne Gifford (hereinafter referred to as \"Wife\") and Grant Taylor Gifford (hereinafter referred to as \"Husband\") subject to the following premises, terms, and conditions:",
            size: 24
          })
        ],
        spacing: { after: 240 }
      }),

      // WITNESSETH
      new Paragraph({
        alignment: AlignmentType.CENTER,
        children: [
          new TextRun({
            text: "WITNESSETH",
            bold: true,
            size: 24
          })
        ],
        spacing: { after: 240 }
      }),

      // WHEREAS clauses
      new Paragraph({
        alignment: AlignmentType.JUSTIFIED,
        children: [
          new TextRun({
            text: "WHEREAS the parties were married on August 18, 2018, and separated on or about June 30, 2025, and have, since the latter date, been living in a bona fide state of separation; and",
            size: 24
          })
        ],
        spacing: { after: 120 }
      }),
      new Paragraph({
        alignment: AlignmentType.JUSTIFIED,
        children: [
          new TextRun({
            text: "WHEREAS the parties have one child of the marriage, D.S.H. (DOB 12/30/2007), but as of the entry of this Agreement, has reached the age of majority and no parenting plan shall be necessary; and",
            size: 24
          })
        ],
        spacing: { after: 120 }
      }),
      new Paragraph({
        alignment: AlignmentType.JUSTIFIED,
        children: [
          new TextRun({
            text: "WHEREAS certain differences and difficulties have arisen between the parties, and a divorce action in which irreconcilable differences is alleged as a ground has been instituted in the Circuit Court for Williamson County, Tennessee, and they have no expectation of resuming their marital relationship;",
            size: 24
          })
        ],
        spacing: { after: 120 }
      }),
      new Paragraph({
        alignment: AlignmentType.JUSTIFIED,
        children: [
          new TextRun({
            text: "WHEREAS the parties have represented each to the other that they have made a full and complete disclosure of all their assets and liabilities;",
            size: 24
          })
        ],
        spacing: { after: 120 }
      }),
      new Paragraph({
        alignment: AlignmentType.JUSTIFIED,
        children: [
          new TextRun({
            text: "WHEREAS the parties desire to enter this Marital Dissolution Agreement to settle all questions relating to spousal support, division of property, liabilities, alimony, expenses of litigation, and any and all other claims or rights of an financial nature whatsoever concerning the parties, and to tender this Agreement to this Honorable Court for approval in the event that a Final Decree of Divorce is granted in this cause;",
            size: 24
          })
        ],
        spacing: { after: 120 }
      }),
      new Paragraph({
        alignment: AlignmentType.JUSTIFIED,
        children: [
          new TextRun({
            text: "WHEREAS Wife is represented by Jeffrey Kuykendall, Esq., and Husband is represented by Hannah Shanley, Esq.",
            size: 24
          })
        ],
        spacing: { after: 240 }
      }),

      // NOW THEREFORE
      new Paragraph({
        alignment: AlignmentType.JUSTIFIED,
        children: [
          new TextRun({
            text: "NOW, THEREFORE, for the reasons set forth above and in consideration of the mutual covenants and agreements set forth herein, the parties agree as follows:",
            size: 24
          })
        ],
        spacing: { after: 240 }
      }),

      // 1. DIVORCE
      new Paragraph({
        alignment: AlignmentType.JUSTIFIED,
        children: [
          new TextRun({
            text: "1. DIVORCE. ",
            bold: true,
            size: 24
          }),
          new TextRun({
            text: "Wife filed a Complaint for Absolute Divorce in the Circuit Court for Williamson County, Tennessee, under Docket No.: 25-CV-543 and shall proceed with obtaining a divorce on the grounds of irreconcilable differences. This Agreement shall be presented to the Court for approval and incorporated into the Final Decree.",
            size: 24
          })
        ],
        spacing: { after: 120 }
      }),
      new Paragraph({
        alignment: AlignmentType.JUSTIFIED,
        indent: { left: 720 },
        children: [
          new TextRun({
            text: "Husband hereby signs this agreement for the purpose of granting Wife a divorce upon the grounds of irreconcilable differences so that it will not be necessary for Husband to appear at the final hearing for absolute divorce in person, unless requested to do so by this Honorable Court.",
            size: 24
          })
        ],
        spacing: { after: 120 }
      }),

      // 2. REAL PROPERTY
      new Paragraph({
        alignment: AlignmentType.JUSTIFIED,
        children: [
          new TextRun({
            text: "2. REAL PROPERTY. ",
            bold: true,
            size: 24
          }),
          new TextRun({
            text: "The parties agree that they do not own any real property.",
            size: 24
          })
        ],
        spacing: { after: 120 }
      }),

      // 3. ALIMONY
      new Paragraph({
        alignment: AlignmentType.JUSTIFIED,
        children: [
          new TextRun({
            text: "3. ALIMONY. ",
            bold: true,
            size: 24
          }),
          new TextRun({
            text: "The parties acknowledge that Wife is not entitled to alimony but agree that Husband shall pay Wife three thousand dollars ($3,000.00) per month. Said payments shall commence on the 6th of the month following the entry of the Final Decree, with the final payment due on August 5, 2026. Upon payment on August 5, 2026, Husband shall be relieved of any financial obligations to Wife for alimony. The parties agree that this award constitutes transitional alimony, pursuant to Tenn. Code Ann. §36-5-121(g),and is non-modifiable as to amount or duration as identified in this Marital Dissolution Agreement.",
            size: 24
          })
        ],
        spacing: { after: 120 }
      }),
      new Paragraph({
        alignment: AlignmentType.JUSTIFIED,
        indent: { left: 720 },
        children: [
          new TextRun({
            text: "Deductions: ",
            bold: true,
            size: 24
          }),
          new TextRun({
            text: "Wife agrees that she shall be solely responsible for the monthly payments for the following obligations: her cellphone, auto insurance, and all obligations associated with the lease of the Kia, totaling six hundred thirty-three dollars ($633.00) per month. Wife agrees to remove Husband's name and liability from all associated accounts or lease obligations, and until such time, Husband shall deduct the above listed sum of $633.00 from the monthly alimony payment. Wife shall receive a total sum of two thousand three hundred seventy-seven dollars ($2,377.00) per month. At such time that Wife removes Husband's name and liability from all associates accounts and obligations, and upon receipt of written confirmation of same, Husband agrees to resume payments to Wife of three thousand dollars ($3,000.00) a month for any remaining months within the above referenced time frame.",
            size: 24
          })
        ],
        spacing: { after: 120 }
      }),

      // 4. PERSONAL PROPERTY
      new Paragraph({
        alignment: AlignmentType.JUSTIFIED,
        children: [
          new TextRun({
            text: "4. PERSONAL PROPERTY. ",
            bold: true,
            size: 24
          }),
          new TextRun({
            text: "The parties have divided between themselves all personal belongings that were acquired during the marriage. Wife shall be awarded all items currently within her possession free and clear of any claim by Husband. Husband shall be awarded all items currently within his possession free and clear of any claim by Wife. Each party makes no claim to any property in the possession of the other party and, by signing this document, quitclaims any interest he or she may have to the property in possession of the other.",
            size: 24
          })
        ],
        spacing: { after: 120 }
      }),

      // 5. ANIMALS
      new Paragraph({
        alignment: AlignmentType.JUSTIFIED,
        children: [
          new TextRun({
            text: "5. ANIMALS. ",
            bold: true,
            size: 24
          }),
          new TextRun({
            text: "The Parties acknowledge that they have two animals: Protier, a Husky, and Aurora, a boxer. Wife will assume ownership and financial responsibility of Protier and Husband will assume ownership and financial responsibility of Aurora. There are two cats that Wife will assume ownership and all financial responsibility.",
            size: 24
          })
        ],
        spacing: { after: 120 }
      }),

      // 6. VEHICLES
      new Paragraph({
        alignment: AlignmentType.JUSTIFIED,
        children: [
          new TextRun({
            text: "6. VEHICLES. ",
            bold: true,
            size: 24
          }),
          new TextRun({
            text: "The Parties acknowledge that there is one vehicle, a Kia, currently leased in both parties' name, and bearing Vehicle Identification Number (______). Wife agrees to remove Husband from the lease and release him of all financial obligations and liability under the lease. Wife shall be solely responsible for all payments associated with the Kia at the time of the entry of the final decree. In the event that Wife is unable to fully assume the lease obligations of the vehicle, Husband agrees to remain on the lease until Wife has the ability to undertake all responsibilities and obligations under the lease. Notwithstanding Husband remaining on the lease, Wife shall continue to be responsible for all monthly financial obligations associated with the Kia.",
            size: 24
          })
        ],
        spacing: { after: 120 }
      }),
      new Paragraph({
        alignment: AlignmentType.JUSTIFIED,
        indent: { left: 720 },
        children: [
          new TextRun({
            text: "Upon Wife's ability to assume all financial responsibility and obligations under the lease, Husband shall execute all appropriate documentation to remove himself from the lease and transfer possession of said vehicle to Wife, solely and separately, within a reasonable time thereafter. Wife shall be solely responsible for all remaining indebtedness, taxes, insurance, registration fees and all remaining costs associated with the vehicle.",
            size: 24
          })
        ],
        spacing: { after: 120 }
      }),
      new Paragraph({
        alignment: AlignmentType.JUSTIFIED,
        indent: { left: 720 },
        children: [
          new TextRun({
            text: "Any interest that the Husband has in the above listed vehicle shall be divested of him and vested fully in Wife. Wife hereby releases and agrees to hold Husband harmless for any future claims, demands, or liabilities associated with the vehicle after the Husband is removed from the lease.",
            size: 24
          })
        ],
        spacing: { after: 120 }
      }),
      new Paragraph({
        alignment: AlignmentType.JUSTIFIED,
        indent: { left: 720 },
        children: [
          new TextRun({
            text: "The Parties acknowledge that Husband has one vehicle titled solely in his name. The Husband shall be awarded the _______________________, bearing the Vehicle Identification Number (________). Any interest that the Wife has in the above listed vehicle shall be divested of her and vested fully in Husband. Husband shall be responsible for all remaining indebtedness, taxes, insurance, registration fees and all remaining costs associated with the vehicle. Husband hereby releases and agrees to hold Wife harmless for any future claims, demands, or liabilities associated with the vehicle after the entry of the Final Decree.",
            size: 24
          })
        ],
        spacing: { after: 120 }
      }),
      new Paragraph({
        alignment: AlignmentType.JUSTIFIED,
        indent: { left: 720 },
        children: [
          new TextRun({
            text: "The Husband acknowledges that a marital vehicle was sold during the pendency of the divorce proceedings. The parties agree that the Wife is entitled to an equalization payment in the amount of Three Thousand Five Hundred Dollars ($3,500.00) representing her share of the proceeds from said sale.",
            size: 24
          })
        ],
        spacing: { after: 120 }
      }),
      new Paragraph({
        alignment: AlignmentType.JUSTIFIED,
        indent: { left: 720 },
        children: [
          new TextRun({
            text: "Husband shall pay Wife the sum of $3,500.00 after the divorce is final. Payment shall be made by certified funds, electronic transfer, or other mutually agreed method.",
            size: 24
          })
        ],
        spacing: { after: 120 }
      }),
      new Paragraph({
        alignment: AlignmentType.JUSTIFIED,
        indent: { left: 720 },
        children: [
          new TextRun({
            text: "Each party releases any claim or right he or she has to the vehicle(s) of the other and by signing this document quit claims any interest he or she may have to the other's vehicle.",
            size: 24
          })
        ],
        spacing: { after: 120 }
      }),

      // 7. HEALTH INSURANCE
      new Paragraph({
        alignment: AlignmentType.JUSTIFIED,
        children: [
          new TextRun({
            text: "7. HEALTH INSURANCE. ",
            bold: true,
            size: 24
          }),
          new TextRun({
            text: "The parties agree that Husband shall maintain health insurance coverage for the child and further agrees to maintain and cover Wife's health insurance through the end of 2026. Wife shall be solely responsible for any additional expenses, beyond those that are covered by the applicable annual deductible. The parties agree that Wife shall maintain her own health insurance beginning the renewal period in 2026.",
            size: 24
          })
        ],
        spacing: { after: 120 }
      }),
      new Paragraph({
        alignment: AlignmentType.JUSTIFIED,
        indent: { left: 720 },
        children: [
          new TextRun({
            text: "Future medical payments: ",
            bold: true,
            size: 24
          }),
          new TextRun({
            text: "The parties agree that any future medical issues relating to Wife's recent cervical spine injury shall be addressed in good faith. Husband agrees to cover expenses directly relating to future medical issues concerning Wife's prior injury, up to the applicable annual deductible. Husband shall not be liable for any other medical expenses incurred by Wife that are unrelated to this specific cervical spine injury and that fall outside the scope of treatment for said injury.",
            size: 24
          })
        ],
        spacing: { after: 120 }
      }),

      // 8. CRYPTO CURRENCY
      new Paragraph({
        alignment: AlignmentType.JUSTIFIED,
        children: [
          new TextRun({
            text: "8. CRYPTO CURRENCY. ",
            bold: true,
            size: 24
          }),
          new TextRun({
            text: "The parties acknowledge that certain cryptocurrency assets are presently held solely in the name of Husband. The parties agree that, within ten (10) days of the entry of the Final Decree, Husband shall liquidate the entirety of the cryptocurrency holdings, at their current market-value at the time of liquidation, and apply all derived funds from the cryptocurrency assets to all debts held jointly. Should any funds remain thereafter, the funds shall be divided equally between the parties. Each Party agrees to hold harmless the other for any debts, fees, taxes, or liabilities on the distributed amount. The funds distributed shall be the sole and separate property of each party.",
            size: 24
          })
        ],
        spacing: { after: 120 }
      }),
      new Paragraph({
        alignment: AlignmentType.JUSTIFIED,
        indent: { left: 720 },
        children: [
          new TextRun({
            text: "Within ten (10) days from the final payment of all debts incurred in both parties' names, Husband shall cooperate in good faith to transfer to the Wife her fifty (50) percent share of any of the remaining Cryptocurrency assets, by direct transfer to Wife. Any Cryptocurrency Assets acquired by Husband after the entry of the Final Decree, held in his name solely or within his control, possession shall be deemed his sole and separate property. Wife hereby waives all rights, claims, or interest on all such assets acquired after the entry of the Final Decree.",
            size: 24
          })
        ],
        spacing: { after: 120 }
      }),
      new Paragraph({
        alignment: AlignmentType.JUSTIFIED,
        indent: { left: 720 },
        children: [
          new TextRun({
            text: "DEBT. ",
            bold: true,
            size: 24
          }),
          new TextRun({
            text: "The parties acknowledge that certain debts and financial obligations were incurred jointly, or individually, during the marriage, in the amount of thirty-four thousand dollars ($34,000.00). The parties acknowledge that the value of cryptocurrency is volatile and fluctuates at an unpredictable rate, either increasing or decreasing, and the exact amount held in cryptocurrency shall be determined at the time of the Final Decree. The parties agree that Husband shall liquidate the entirety of the cryptocurrency holdings, at the time of the entry of the Final Decree, and apply all holdings to the outstanding debt.",
            size: 24
          })
        ],
        spacing: { after: 120 }
      }),
      new Paragraph({
        alignment: AlignmentType.JUSTIFIED,
        indent: { left: 720 },
        children: [
          new TextRun({
            text: "Husband agrees to pay three monthly installments of eleven thousand three hundred thirty-three dollars ($11,333.00) towards the debt, beginning on the fifth of the month following the entry of the Final Decree. The parties agree that any outstanding debts, not covered by the liquidated cryptocurrency assets, shall be distributed equally between the parties.",
            size: 24
          })
        ],
        spacing: { after: 120 }
      }),
      new Paragraph({
        alignment: AlignmentType.JUSTIFIED,
        indent: { left: 720 },
        children: [
          new TextRun({
            text: "Each party shall be solely responsible for any debt, liabilities or obligations held in their name, individually, whether incurred before or after the entry of the Final Decree. Each Party agrees to indemnify and hold the other harmless from any claims, demands, or expenses arising from any debts or obligations for which they are individually liable.",
            size: 24
          })
        ],
        spacing: { after: 120 }
      }),
      new Paragraph({
        alignment: AlignmentType.JUSTIFIED,
        indent: { left: 720 },
        children: [
          new TextRun({
            text: "Iberostar account: ",
            bold: true,
            size: 24
          }),
          new TextRun({
            text: "The parties acknowledge that an Iberostar Account (Account No.: ______), is held jointly in both of their names. The parties agree that Wife shall use the $6,000 credit on the account towards the minor child's senior graduation trip to Mexico.",
            size: 24
          })
        ],
        spacing: { after: 120 }
      }),
      new Paragraph({
        alignment: AlignmentType.JUSTIFIED,
        indent: { left: 720 },
        children: [
          new TextRun({
            text: "The parties agree that Wife shall be removed from the account upon the completion of the minor child's graduation trip. The Iberostar account shall be the sole and separate property of the Husband. The parties acknowledge that Husband, at his own discretion, may make additional deposits or contributions to the account upon execution of the disbursement. Any such future contributions, interest, or appreciation derived therefrom shall be the sole and separate of the Husband. Husband shall be liable for all debts and liabilities incurred after the disbursement. Husband agrees to hold Wife Harmless for any debts or liabilities incurred after distribution. Wife agrees to waive all rights, claims, or interest on the account upon the conclusion of the minor child's graduation trip.",
            size: 24
          })
        ],
        spacing: { after: 120 }
      }),

      // 9. RETIREMENT ACCOUNTS
      new Paragraph({
        alignment: AlignmentType.JUSTIFIED,
        children: [
          new TextRun({
            text: "9. RETIREMENT ACCOUNTS. ",
            bold: true,
            size: 24
          }),
          new TextRun({
            text: "The parties acknowledge that Husband has a 401k retirement account, held in ________ bank, held solely in Husband's name. The parties agree that the account shall be the sole and separate property of the Husband and shall remain in his exclusive possession and control. Wife hereby waives all rights, claims, or interest to the above listed account and agrees the account shall be free and clear of any claims made by her.",
            size: 24
          })
        ],
        spacing: { after: 120 }
      }),
      new Paragraph({
        alignment: AlignmentType.JUSTIFIED,
        indent: { left: 720 },
        children: [
          new TextRun({
            text: "The parties acknowledge that there is a Fidelity Account (Account No.: ) held solely in the Wife's name. The parties agree that the account is the sole and separate property of the Wife and shall remain in her exclusive possession and control. Husband hereby waives all rights, claims, or interest he may have in the above listed account, and agrees the account shall be free and clear of any claims made by him.",
            size: 24
          })
        ],
        spacing: { after: 120 }
      }),
      new Paragraph({
        alignment: AlignmentType.JUSTIFIED,
        indent: { left: 720 },
        children: [
          new TextRun({
            text: "BANK ACCOUNTS. ",
            bold: true,
            size: 24
          }),
          new TextRun({
            text: "The parties acknowledge that there are three joint accounts, 2 checking accounts with _____________ bank, and 1 savings account at _______________ bank. The parties agree that the joint bank account, account ending in *6607, shall be transferred to Husband and ownership of the account shall be changed within ten (10) days of the entry of the Final Decree. Wife shall cooperate in good faith to execute all documentation, instruments, or authorizations reasonably necessary to effectuate the removal of her respective name from the applicable account upon its closure, and make herself reasonably available for any in person meetings necessary to effectuate the removal. Upon the closing of the Joint Account, the Parties agree to not open or maintain any joint bank account or financial account with the other Party.",
            size: 24
          })
        ],
        spacing: { after: 120 }
      }),
      new Paragraph({
        alignment: AlignmentType.JUSTIFIED,
        indent: { left: 720 },
        children: [
          new TextRun({
            text: "Wife shall remove any bills, held in her name individually, or her sole responsibility, attached to the account within ten (10) days of the entry of the Final Decree. Should any funds be removed or deducted from the account after ownership is changed to Husband, individually, all funds withdrawn shall be deducted from Wife's monthly alimony payments. Wife waives all rights, interests, or claims to the funds held in the account.",
            size: 24
          })
        ],
        spacing: { after: 120 }
      }),
      new Paragraph({
        alignment: AlignmentType.JUSTIFIED,
        indent: { left: 720 },
        children: [
          new TextRun({
            text: "The Parties agree that the checking account, maintained by the Wife, and all funds held therein at the time of closing the account, shall be the sole and separate property of the Wife. Husband waives all rights, interests, or claims in the funds held in the account.",
            size: 24
          })
        ],
        spacing: { after: 120 }
      }),
      new Paragraph({
        alignment: AlignmentType.JUSTIFIED,
        indent: { left: 720 },
        children: [
          new TextRun({
            text: "The parties acknowledge that they currently maintain accounts held solely in their names, individually. Each party shall have the right to manage and maintain their own individual accounts held in their name solely. Each party shall have all rights, title, and interest to any personal checking or savings account of any kind, held in his or her name with sole ownership and control over their respective accounts. The other Party shall have no claim, rights, or interest to any account or funds held therein.",
            size: 24
          })
        ],
        spacing: { after: 120 }
      }),

      // 10. LIMITED LIABILITY COMPANY
      new Paragraph({
        alignment: AlignmentType.JUSTIFIED,
        children: [
          new TextRun({
            text: "10. LIMITED LIABILITY COMPANY. ",
            bold: true,
            size: 24
          }),
          new TextRun({
            text: "The parties acknowledge that Wife is the sole owner of Aesthetic and Wellness Growth Agency, a Limited Liability Company, including business interest, assets, proceeds, property, accounts, contracts, debts, liabilities, and any other property, tangible or intangible, associated with the company. The parties agree that all proceeds derived therefrom, including profits, proceeds, income, or any form of compensation shall remain the sole and separate property of the Wife.",
            size: 24
          })
        ],
        spacing: { after: 120 }
      }),
      new Paragraph({
        alignment: AlignmentType.JUSTIFIED,
        indent: { left: 720 },
        children: [
          new TextRun({
            text: "Husband shall not pursue, commence, or initiate any legal proceedings against the company, its capital earnings, or successors arising from or connected with the business, whether known or unknown. Husband waives any and all present and future claims, rights, or interest in the business.",
            size: 24
          })
        ],
        spacing: { after: 120 }
      }),
      new Paragraph({
        alignment: AlignmentType.JUSTIFIED,
        indent: { left: 720 },
        children: [
          new TextRun({
            text: "Wife shall have the exclusive authority to operate, manage, and control the business without interference, consent, or participation from Husband. Wife agrees to hold Husband harmless of any debts or liabilities associated with the Business.",
            size: 24
          })
        ],
        spacing: { after: 120 }
      }),
      new Paragraph({
        alignment: AlignmentType.JUSTIFIED,
        indent: { left: 720 },
        children: [
          new TextRun({
            text: "ATTORNEYS FEES. ",
